import type { Metadata } from "next";
import { site } from "./site";

/** The typographic social card generated by src/app/opengraph-image.tsx. */
const defaultImage = [
  {
    url: "/opengraph-image",
    width: 1200,
    height: 630,
    alt: "ArtbyMoon: paintings, polaroids, bookmarks and photographs",
  },
];

/**
 * Per-page metadata: title, description, canonical URL (always the clean
 * path, so ?review and filter URLs consolidate onto it) and Open Graph.
 * The social image comes from the file-based src/app/opengraph-image.tsx
 * unless a page supplies its own.
 */
export function pageMetadata({
  title,
  description,
  path,
  images,
}: {
  title?: string;
  description: string;
  path: `/${string}`;
  images?: NonNullable<Metadata["openGraph"]>["images"];
}): Metadata {
  return {
    ...(title && { title }),
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: site.name,
      locale: "en_GB",
      url: path,
      title: title ? `${title} | ${site.name}` : undefined,
      description,
      // A page-level openGraph replaces the parent one, dropping the root
      // file-based image, so the shared default is restated here.
      images: images ?? defaultImage,
    },
    twitter: { card: "summary_large_image", images: images ?? defaultImage },
  };
}
